It's the same with `import()`:
```javascript
const sameModule = await import('./deps/a-module');
sameModule.subModule(); // outputs: 'now in sub module'
    
const sameModuleName = 'a-module';
const { subModule } = await import(`./deps/${name}`);  // throws Uncaught (in promise) Error: Cannot find module './'.
subModule();
```

Another example:
```javascript
const path = `./deps/${'a-module'}`
console.log(path); // outputs: ./deps/a-module
const { subModule } = await import(path);  // Uncaught (in promise) Error: Cannot find module './deps/a-module'.
subModule();
```

Just to make sure there wasn't anything else going on:
```javascript
require.ensure([], () => {
    const { subModule } = require(`./deps/${'a-module'}`);
    subModule();  // outputs: now in sub module
});

Yes, and it works without the subpath.

```javascript
const sameModule = await import('./a-module');
sameModule.subModule(); // outputs 'now in sub module'
    
const sameModuleName = 'a-module';
const sameModule = await import(`./${name}`);  
sameModule.subModule(); // outputs 'now in sub module'
```

Which leads me to believe it should work with paths more complex than `./` too.

Surely a better fix must exist for this issue than doing something like this:

```javascript

    _loadPage(name) {
        const page = PageComponents[this.currentPage.name];

        let load = {
            HomePage: System.import('../components/HomePage'),
            ErrorPage: System.import('../components/ErrorPage'),
            EssentialKnowledgePage: System.import('../components/EssentialKnowledgePage'),
            SubjectExamPage: System.import('../components/SubjectExamPage'),
            TeachingExamPage: System.import('../components/TeachingExamPage'),
            ContractPage: System.import('../components/ContractPage'),
            BackgroundPage: System.import('../components/BackgroundPage'),
            SchedulePage: System.import('../components/SchedulePage')
        }[page];

        load
              .then(action(module => this.currentPage.component = module.default))
              .catch(err => this.showAlert({message: 'Error loading page component'}));
    }
```

This works:
```javascript
function systemImportLoad(subModule) {
    return System.import('./deps/modules/' + subModule + '/index.js');
}

function importLoad(subModule) {
    return import('./deps/modules/' + subModule + '/index.js');
}

systemImportLoad('sub-folder-module-a').then(module => module.default());
systemImportLoad('sub-folder-module-b').then(module => module.default());

importLoad('sub-folder-module-a').then(module => module.default());
importLoad('sub-folder-module-b').then(module => module.default());
```
Output:
```
in sub folder module a
in sub folder module a
in sub folder module b
in sub folder module b
```

This does not work (without `+ '/index.js'`):
```javascript
function systemImportLoad(subModule) {
    return System.import('./deps/modules/' + subModule);
}

function importLoad(subModule) {
    return import('./deps/modules/' + subModule);
}

systemImportLoad('sub-folder-module-a').then(module => module.default());
systemImportLoad('sub-folder-module-b').then(module => module.default());

importLoad('sub-folder-module-a').then(module => module.default());
importLoad('sub-folder-module-b').then(module => module.default());
```

As a final test I disabled `babel-loader`and created a small config, to try it out as much out-of-the-box as possible. Same results.

Gist with all code, including generated and package.json:
https://gist.github.com/jouni-kantola/26f211781956e6d2a1aec8054e0415d8

Code:
```javascript
function load(subModule) {
    return System.import('./modules/' + subModule);
}

// works
load('module-a/index.js').then(a => {
    console.log('module-a/index.js');
    a();
});

// throws
load('module-a/').then(a => {
    console.log('module-a/');
    a();
});

// throws
load('module-a').then(a => {
    console.log('module-a');
    a();
});
```
